/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var isObject = require( '@stdlib/assert/is-object' );
var isUndefined = require( '@stdlib/assert/is-undefined' );
var objectAssignIn = require( '@stdlib/object/assign-in' );
var format = require( '@stdlib/string/format' );
var changeEvent = require( './../change_event.js' );
var prop = require( './properties.js' );


// VARIABLES //

var debug = logger( 'vega:legend:set:'+prop.name );


// MAIN //

/**
* Sets the desired number of tick values for quantitative legends.
*
* ## Notes
*
* -   Providing `undefined` "unsets" the configured value.
*
* @private
* @param {(number|string|Object|void)} value - input value
* @throws {TypeError} must be a number, string, or object
* @returns {void}
*/
function set( value ) {
	var isObj = isObject( value );

	// FIXME: validate legal string values
	if ( !isObj && !isNumber( value ) && !isString( value ) && !isUndefined( value ) ) { // eslint-disable-line max-len
		throw new TypeError( format( 'invalid assignment. `%s` must be a number, a string, or a valid object-valued interval specifier. Value: `%s`.', prop.name, value ) );
	}

	// FIXME: ensure validate object-valued interval specifier

	// TODO: should we deep inspect an object-valued specified to prevent false positive change events?

	if ( value !== this[ prop.private ] ) {
		debug( 'Current value: %s. New value: %s.', this[ prop.private ], value );
		this[ prop.private ] = ( isObj ) ? objectAssignIn( {}, value ) : value;
		this.emit( 'change', changeEvent( prop.name ) );
	}
}


// EXPORTS //

module.exports = set;
